'use client'

import { useId, useMemo, useState } from 'react'
import { judgeEvidence, type AvailableValue, type EvidenceRow } from './evidence'
import { cx, formatWhen } from './util'
import { after } from './theatre'

export type EvidenceTableProps = {
  title: string
  rows: EvidenceRow[]
  /** Your document text by id. A source with a `docId` has its excerpt looked up in it, and one that is not there is flagged. */
  documents?: Record<string, string>
  /** What the source documents contain, so values the agent left out can be named. */
  available?: AvailableValue[]
  className?: string
}

type Filter = 'all' | 'unsourced' | 'conflict' | 'unverified'

/**
 * Each extracted value with the places it was read from. Coverage and conflicts are counted from the sources. There
 * is no confidence score: a value has a source or it does not, and two sources either agree or they do not.
 */
export function EvidenceTable({ title, rows, documents, available, className }: EvidenceTableProps) {
  const { rows: judged, omitted, summary } = useMemo(() => judgeEvidence(rows, { documents, available }), [rows, documents, available])
  const [filter, setFilter] = useState<Filter>('all')
  const [open, setOpen] = useState<Set<string>>(() => new Set(judged.filter((j) => j.status === 'conflict' || j.status === 'unverified').map((j) => j.row.id)))
  const base = useId()
  const shown = judged.filter((j) => filter === 'all' || j.status === filter)
  const toggle = (id: string) => setOpen((s) => {
    const next = new Set(s)
    if (next.has(id)) next.delete(id)
    else next.add(id)
    return next
  })
  const allSourced = summary.total > 0 && summary.unsourced === 0 && summary.conflicts === 0 && summary.unverified === 0 && summary.omitted === 0
  return (
    <section role="group" className={cx('ol', className)} aria-label={title}>
      <div className="ol-head-row">
        <strong>{title}</strong>
        <span className="ol-pill" data-tone={allSourced ? 'good' : summary.conflicts || summary.unverified ? 'bad' : 'warn'}>{summary.text}</span>
      </div>
      <div className="ol-chips" role="group" aria-label="Show">
        {([['all', 'All', summary.total], ['unsourced', 'No source', summary.unsourced], ['conflict', 'Conflict', summary.conflicts], ['unverified', 'Quote not found', summary.unverified]] as const).map(([id, label, n]) => (
          <button key={id} type="button" className="ol-chip" aria-pressed={filter === id} onClick={() => setFilter(id)}>{label} {n}</button>
        ))}
      </div>
      {shown.length === 0 ? (
        <p className="ol-sub" role="status">{summary.total === 0 ? 'No values yet.' : 'Nothing matches.'}</p>
      ) : (
        <ul className="ol-evlist">
          {shown.map(({ row, status, conflicts, checks }, idx) => {
            const expanded = open.has(row.id)
            const id = `${base}-${row.id}`
            return (
              <li key={row.id} className="ol-evrow ol-in" style={after(idx)} data-status={status}>
                <button type="button" className="ol-evbtn" aria-label={`${row.field}: ${row.value}. ${status === 'unsourced' ? 'No source' : status === 'conflict' ? 'Sources conflict' : status === 'unverified' ? 'A quote is not in its document' : `${row.sources.length} ${row.sources.length === 1 ? 'source' : 'sources'}`}`} aria-expanded={expanded} aria-controls={id} onClick={() => toggle(row.id)}>
                  <span className="ol-evfield">{row.field}</span>
                  <span className="ol-evval">{row.value}</span>
                  <span className="ol-pill" data-tone={status === 'conflict' || status === 'unverified' ? 'bad' : status === 'unsourced' ? 'warn' : 'good'}>
                    {status === 'unsourced' ? 'No source' : status === 'conflict' ? 'Conflict' : status === 'unverified' ? 'Quote not found' : row.sources.length === 1 ? '1 source' : `${row.sources.length} sources`}
                  </span>
                </button>
                {expanded && (
                  <ul id={id} className="ol-evsrcs">
                    {row.sources.length === 0 && <li className="ol-sub">Nothing in the record says where this came from.</li>}
                    {row.sources.map((s) => {
                      const bad = conflicts.includes(s)
                      return (
                        <li key={s.id} className="ol-evsrc">
                          <span><b>{s.label}</b>{s.locator && <span className="ol-sub"> {s.locator}</span>}{s.readAt && <span className="ol-sub"> read {formatWhen(s.readAt)}</span>}</span>
                          {s.read !== undefined && <span className={bad ? 'ol-evread ol-evbad' : 'ol-evread'}>{bad ? `Says ${s.read}` : `Says ${s.read}, matches`}</span>}
                          {s.excerpt && <blockquote className="ol-excerpt">{s.excerpt}</blockquote>}
                          {checks[s.id]?.quote === 'found' && <span className="ol-sub">The quote is in the document.</span>}
                          {checks[s.id]?.quote === 'not-found' && <span className="ol-evread ol-evbad">This quote is not in the document.</span>}
                          {checks[s.id]?.excerptHasRead === false && <span className="ol-evread ol-evbad">The quote does not contain {s.read}.</span>}
                        </li>
                      )
                    })}
                  </ul>
                )}
              </li>
            )
          })}
        </ul>
      )}
      {omitted.length > 0 && (
        <div className="ol-gatelist">
          <p className="ol-sub">In the source, not extracted</p>
          <ul>{omitted.map((o) => <li key={o.id}><span>{o.field}: {o.value}</span>{o.locator && <span className="ol-sub">{o.locator}</span>}</li>)}</ul>
        </div>
      )}
    </section>
  )
}

// Rules for showing where each extracted value came from. The point of each: a value is sourced or it is not, and
// two sources that disagree are a conflict, whatever a model says about its confidence.

/** One place a value was read from. `read` is what that source says, when it differs or needs checking. */
export type EvidenceSource = {
  id: string
  label: string
  locator?: string
  excerpt?: string
  read?: string
  readAt?: string
  /** Which of your documents this came from, so the excerpt can be found in its text. */
  docId?: string
}
export type EvidenceRow = { id: string; field: string; value: string; sources: EvidenceSource[] }
export type RowStatus = 'sourced' | 'unsourced' | 'conflict' | 'unverified'
/** `found`: the excerpt is in the document. `not-found`: it is not, so it was not quoted from there. `unchecked`: no document to look in. */
export type QuoteCheck = 'found' | 'not-found' | 'unchecked'
export type SourceCheck = { quote: QuoteCheck; /** Whether the excerpt contains the value the source is said to read. `null` when there is nothing to compare. */ excerptHasRead: boolean | null }
/** A value that is in the source documents, so it can be compared with what was extracted. */
export type AvailableValue = { id: string; field: string; value: string; docId?: string; locator?: string }
export type JudgedRow = { row: EvidenceRow; status: RowStatus; conflicts: EvidenceSource[]; checks: Record<string, SourceCheck> }
export type EvidenceSummary = {
  total: number
  withSource: number
  unsourced: number
  conflicts: number
  /** Rows with a quote that is not in its document. */
  unverified: number
  /** Values in the source that no row covers. */
  omitted: number
  text: string
}
export type EvidenceOptions = { documents?: Record<string, string>; available?: AvailableValue[] }

/** Money and numbers compare as numbers ("$12,400.00" equals "12400"). Everything else compares as trimmed, lower-case words. */
export function sameValue(a: string, b: string): boolean {
  const num = (s: string) => {
    const t = s.replace(/[,$£€\s]/g, '')
    return /^-?\d+(\.\d+)?$/.test(t) ? Number(t) : null
  }
  const x = num(a)
  const y = num(b)
  if (x !== null && y !== null) return x === y
  const words = (s: string) => s.trim().toLowerCase().replace(/\s+/g, ' ')
  return words(a) === words(b)
}

/** Quotes compare ignoring case, runs of spaces and curly quotes, so a line break in a PDF does not hide a real quote. */
const squash = (t: string) => t.replace(/[\u2018\u2019]/g, "'").replace(/[\u201C\u201D]/g, '"').replace(/\s+/g, ' ').trim().toLowerCase()

function hasValue(text: string, value: string): boolean {
  if (squash(text).includes(squash(value))) return true
  const wanted = Number(value.replace(/[,$£€\s]/g, ''))
  if (!Number.isFinite(wanted) || value.trim() === '') return false
  return (text.match(/-?\d[\d,]*(?:\.\d+)?/g) ?? []).some((t) => Number(t.replace(/,/g, '')) === wanted)
}

export function checkSource(s: EvidenceSource, documents?: Record<string, string>): SourceCheck {
  const doc = s.docId !== undefined && documents && Object.hasOwn(documents, s.docId) ? documents[s.docId] : undefined
  const quote: QuoteCheck = !s.excerpt || doc === undefined ? 'unchecked' : squash(doc).includes(squash(s.excerpt)) ? 'found' : 'not-found'
  const excerptHasRead = s.excerpt && s.read !== undefined ? hasValue(s.excerpt, s.read) : null
  return { quote, excerptHasRead }
}

export function judgeEvidence(rows: EvidenceRow[], options: EvidenceOptions = {}): { rows: JudgedRow[]; omitted: AvailableValue[]; summary: EvidenceSummary } {
  const judged = rows.map((row): JudgedRow => {
    const conflicts = row.sources.filter((s) => s.read !== undefined && !sameValue(s.read, row.value))
    const checks = Object.fromEntries(row.sources.map((s) => [s.id, checkSource(s, options.documents)]))
    const unverified = row.sources.some((s) => checks[s.id]!.quote === 'not-found' || checks[s.id]!.excerptHasRead === false)
    const status: RowStatus = conflicts.length ? 'conflict' : unverified ? 'unverified' : row.sources.length ? 'sourced' : 'unsourced'
    return { row, status, conflicts, checks }
  })
  const covered = new Set(rows.map((r) => squash(r.field)))
  const omitted = (options.available ?? []).filter((a) => !covered.has(squash(a.field)))
  const total = rows.length
  const withSource = judged.filter((j) => j.row.sources.length > 0).length
  const unsourced = judged.filter((j) => j.status === 'unsourced').length
  const conflicts = judged.filter((j) => j.status === 'conflict').length
  const unverified = judged.filter((j) => j.status === 'unverified').length
  const parts = [`${withSource} of ${total} values have a source`]
  if (conflicts) parts.push(`${conflicts} in conflict`)
  if (unverified) parts.push(`${unverified} with a quote that is not in the document`)
  if (omitted.length) parts.push(`${omitted.length} in the source not extracted`)
  const text = total === 0 && omitted.length === 0 ? 'No values yet.' : parts.join(', ')
  return { rows: judged, omitted, summary: { total, withSource, unsourced, conflicts, unverified, omitted: omitted.length, text } }
}
